#nullable enable // autogenerated

using System.Collections.Generic;
using System.Xml;
using MVZ2.IO;
using MVZ2Logic.Resources;
using PVZEngine.Tools.Unity;

namespace MVZ2.Metas
{
    public class AchievementMeta
    {
        public AchievementMeta(string id)
        {
            ID = id;
        }

        public string ID { get; private set; }
        public string Name { get; private set; } = string.Empty;
        public string Description { get; private set; } = string.Empty;
        public AchievementType Type { get; private set; } = AchievementType.Achievement;
        public SpriteReference? Icon { get; private set; }
        public XMLConditionList? Unlock { get; private set; }
        public XMLConditionList? HiddenUntil { get; private set; }
        public static AchievementMeta? FromXmlNode(XmlNode node, string defaultNsp)
        {
            var id = node.GetAttribute("id");
            if (string.IsNullOrEmpty(id))
            {
                Log.LogError("The ID of an AchievementMeta is invalid.");
                return null;
            }
            var type = GetTypeByName(node.Name);
            var name = node.GetAttribute("name") ?? string.Empty;
            var description = node.GetAttribute("description") ?? string.Empty;
            var icon = node.GetAttributeSpriteReference("icon", defaultNsp);
            var unlock = node.GetUnlockConditionsOrObsolete("unlock", "unlock", defaultNsp);
            XMLConditionList? hiddenUntil = null;
            var hiddenUntilNode = node["hiddenUntil"];
            if (hiddenUntilNode != null)
            {
                hiddenUntil = XMLConditionList.FromXmlNode(hiddenUntilNode, defaultNsp);
            }
            return new AchievementMeta(id)
            {
                Name = name,
                Type = type,
                Description = description,
                Icon = icon,
                Unlock = unlock,
                HiddenUntil = hiddenUntil,
            };
        }
        public static AchievementType GetTypeByName(string name)
        {
            return achievementTypes.TryGetValue(name, out var type) ? type : AchievementType.Achievement;
        }
        private static readonly Dictionary<string, AchievementType> achievementTypes = new Dictionary<string, AchievementType>()
        {
            { "achievement", AchievementType.Achievement },
            { "notify", AchievementType.Notify },
        };
    }
    public enum AchievementType
    {
        Achievement,
        Notify
    }
}
